#!/usr/bin/env node
/**
 * Materialize the consolidated mapreduce NDJSON into a persistent DuckDB file.
 *
 * The input is the consolidated file metadata / import join output generated by
 * scripts/atlas/mapreduce-consolidated-index.mjs. This step keeps the offline
 * synthesis lane bounded and reproducible by promoting the mapreduce result into
 * a local DuckDB database for downstream inspection.
 */

import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '../..');
const DUCKDB = process.env.DUCKDB_BIN || 'C:\\Users\\james\\AppData\\Local\\Programs\\DuckDB\\duckdb.exe';

const args = new Set(process.argv.slice(2));
const DRY_RUN = args.has('--dry-run') || !args.has('--write');
const INPUT = path.join(ROOT, '.tmp', 'offline-synthesis', 'consolidated-index.ndjson');
const MANIFEST = `${INPUT}.manifest.json`;
const DB_PATH = path.join(ROOT, 'docs', 'reports', 'offline-synthesis-mapreduce.duckdb');
const REPORT_JSON = path.join(ROOT, 'docs', 'reports', 'offline-synthesis-mapreduce-duckdb-report.json');
const REPORT_MD = path.join(ROOT, 'docs', 'reports', 'offline-synthesis-mapreduce-duckdb-report.md');

function mustExist(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Missing required file: ${filePath}`);
  }
}

function runDuckdb(sql, dbPath = DB_PATH) {
  const res = spawnSync(DUCKDB, [dbPath, '-c', sql], { encoding: 'utf8' });
  if (res.error) throw res.error;
  if (res.status !== 0) {
    throw new Error((res.stderr || res.stdout || '').trim() || `duckdb exited ${res.status}`);
  }
  return (res.stdout || '').trim();
}

function runDuckdbJson(sql, dbPath = DB_PATH) {
  const res = spawnSync(DUCKDB, [dbPath, '-json', '-c', sql], { encoding: 'utf8' });
  if (res.error) throw res.error;
  if (res.status !== 0) {
    throw new Error((res.stderr || res.stdout || '').trim() || `duckdb exited ${res.status}`);
  }
  return JSON.parse(res.stdout || '[]');
}

function renderMarkdown(report) {
  const lines = [
    '# Offline Synthesis MapReduce DuckDB',
    '',
    `Generated: ${report.generatedAt}`,
    `Mode: ${report.summary.applied ? 'WRITE' : 'DRY-RUN'}`,
    '',
    '## Summary',
    `- rows: ${report.summary.rows}`,
    `- files: ${report.summary.files}`,
    `- features: ${report.summary.features}`,
    `- static imports: ${report.summary.staticImports}`,
    `- dynamic imports: ${report.summary.dynamicImports}`,
    '',
    '## Top Features',
    ...report.topFeatures.slice(0, 10).map((entry) => `- ${entry.key}: ${entry.value}`),
    '',
    '## Top Extensions',
    ...report.topExtensions.slice(0, 10).map((entry) => `- ${entry.key}: ${entry.value}`),
    '',
    '## Notes',
    '- The mapreduce NDJSON is mirrored into DuckDB so offline synthesis can query the consolidated file graph without re-scanning the repo.',
    '- This lane keeps the same durable sourceRef and feature joins used by the Parent Atlas lane.',
  ];
  return `${lines.join('\n')}\n`;
}

function main() {
  mustExist(INPUT);
  mustExist(MANIFEST);

  const manifest = JSON.parse(fs.readFileSync(MANIFEST, 'utf8'));
  const rows = Array.isArray(manifest?.totalDocuments) ? manifest.totalDocuments : Number(manifest?.totalDocuments ?? 0);
  const output = {
    generatedAt: new Date().toISOString(),
    inputs: {
      input: path.relative(ROOT, INPUT).replace(/\\/g, '/'),
      manifest: path.relative(ROOT, MANIFEST).replace(/\\/g, '/'),
      duckdb: path.relative(ROOT, DB_PATH).replace(/\\/g, '/'),
    },
    summary: {
      rows: Number(rows || 0),
      files: Number(manifest?.statistics?.totalFiles ?? 0),
      features: Object.keys(manifest?.statistics?.byFeature ?? {}).length,
      staticImports: Number(manifest?.statistics?.totalStaticImports ?? 0),
      dynamicImports: Number(manifest?.statistics?.totalDynamicImports ?? 0),
      applied: false,
    },
    topFeatures: Object.entries(manifest?.statistics?.byFeature ?? {})
      .sort((a, b) => b[1] - a[1])
      .map(([key, value]) => ({ key, value })),
    topExtensions: Object.entries(manifest?.statistics?.byExtension ?? {})
      .sort((a, b) => b[1] - a[1])
      .map(([key, value]) => ({ key, value })),
  };

  if (DRY_RUN) {
    fs.mkdirSync(path.dirname(REPORT_JSON), { recursive: true });
    fs.writeFileSync(REPORT_JSON, JSON.stringify(output, null, 2), 'utf8');
    fs.writeFileSync(REPORT_MD, renderMarkdown(output), 'utf8');
    console.log(`Wrote ${REPORT_JSON}`);
    console.log(`Wrote ${REPORT_MD}`);
    console.log('Dry run only — DuckDB not written.');
    return;
  }

  const dbDir = path.dirname(DB_PATH);
  fs.mkdirSync(dbDir, { recursive: true });

  const sql = `
    INSTALL json;
    LOAD json;
    CREATE OR REPLACE TABLE mapreduce_consolidated_index AS
      SELECT * FROM read_ndjson_auto('${INPUT.replace(/\\/g, '/').replace(/'/g, "''")}');
    CREATE OR REPLACE TABLE mapreduce_consolidated_index_meta AS
      SELECT
        count(*)::BIGINT AS rows,
        count(DISTINCT feature)::BIGINT AS features,
        count(DISTINCT extension)::BIGINT AS extensions,
        sum(COALESCE(array_length(staticImports), 0))::BIGINT AS static_imports,
        sum(COALESCE(array_length(dynamicImports), 0))::BIGINT AS dynamic_imports
      FROM mapreduce_consolidated_index;
    PRAGMA database_size;
  `;

  runDuckdb(sql);

  const metaRows = runDuckdbJson('SELECT * FROM mapreduce_consolidated_index_meta;');
  const meta = metaRows[0] ?? { rows: 0, features: 0, extensions: 0, static_imports: 0, dynamic_imports: 0 };

  const report = {
    ...output,
    summary: {
      rows: Number(meta.rows ?? 0),
      files: Number(manifest?.statistics?.totalFiles ?? 0),
      features: Number(meta.features ?? 0),
      extensions: Number(meta.extensions ?? 0),
      staticImports: Number(meta.static_imports ?? 0),
      dynamicImports: Number(meta.dynamic_imports ?? 0),
      applied: true,
    },
  };

  fs.writeFileSync(REPORT_JSON, JSON.stringify(report, null, 2), 'utf8');
  fs.writeFileSync(REPORT_MD, renderMarkdown(report), 'utf8');
  console.log(`Wrote ${REPORT_JSON}`);
  console.log(`Wrote ${REPORT_MD}`);
  console.log(`Wrote ${DB_PATH}`);
  console.log(`Rows: ${report.summary.rows}`);
}

try {
  main();
} catch (error) {
  fs.mkdirSync(path.dirname(REPORT_JSON), { recursive: true });
  fs.writeFileSync(
    REPORT_JSON,
    JSON.stringify(
      {
        generatedAt: new Date().toISOString(),
        error: error?.message ?? String(error),
        inputs: {
          input: path.relative(ROOT, INPUT).replace(/\\/g, '/'),
          manifest: path.relative(ROOT, MANIFEST).replace(/\\/g, '/'),
          duckdb: path.relative(ROOT, DB_PATH).replace(/\\/g, '/'),
        },
      },
      null,
      2
    ),
    'utf8'
  );
  console.error(`[offline synthesis mapreduce duckdb] ${error?.message ?? String(error)}`);
  process.exit(1);
}
